function setupProductStructureEditor(item){const id=Number(item?.id||0),family=id?familyForItem(id):null,bundle=id?bundleForItem(id):null;variantDraft=family?(family.members||[]).map(m=>({item_id:Number(m.item_id),label:String(m.label||''),sort_order:Number(m.sort_order||0)})):(id?[{item_id:id,label:'',sort_order:10}]:[]);bundleDraft=bundle?(bundle.components||[]).map(c=>({component_item_id:Number(c.component_item_id),mode:String(c.mode||'fixed'),quantity:Number(c.quantity||1),price_delta:Number(c.price_delta||0),sort_order:Number(c.sort_order||0)})):[];const ve=$('[data-variant-enabled]');if(ve)ve.checked=!!family;const editor=$('[data-variant-editor]');if(editor)editor.hidden=!family;const vn=$('[data-variant-name]');if(vn)vn.value=family?.name||item?.name||'';const vd=$('[data-variant-description]');if(vd)vd.value=family?.description||'';const be=$('[data-bundle-enabled]');if(be)be.checked=!!bundle;const bed=$('[data-bundle-editor]');if(bed)bed.hidden=!bundle;const bl=$('[data-bundle-choice-label]');if(bl)bl.value=bundle?.choice_label||'';renderVariantMembers(id);renderBundleComponents(id);renderSuggestionSelectors(id)}
function renderVariantMembers(currentId=0){const box=$('[data-variant-members]');if(!box)return;box.replaceChildren();const items=activeStructureItems();variantDraft.forEach((r,idx)=>{const row=el('div','sc-product-structure-row');const sel=optionSelect(items,r.item_id);sel.dataset.variantItem=String(idx);sel.required=true;sel.addEventListener('change',()=>{r.item_id=Number(sel.value||0);I?.markDirty?.($('[data-item-form]'))});const label=document.createElement('input');label.className='sc-control';label.placeholder='عنوان مثل کوچک / بزرگ';label.value=r.label||'';label.maxLength=80;label.addEventListener('input',()=>{r.label=label.value;I?.markDirty?.($('[data-item-form]'))});const del=button('حذف',()=>{variantDraft.splice(idx,1);renderVariantMembers(currentId);I?.markDirty?.($('[data-item-form]'))},'secondary');row.append(sel,label,del);box.append(row)});if(!variantDraft.length)box.append(el('div','sc-empty','حداقل دو Variant اضافه کن.'))}
