function renderSuggestionSelectors(currentId=0){const candidates=activeStructureItems(currentId);for(let idx=0;idx<2;idx++){const old=$(`[data-suggestion="${idx}"]`);if(!old)continue;const selected=Number(suggestionIdsFor(currentId)[idx]||0);old.replaceChildren();const z=document.createElement('option');z.value='0';z.textContent='بدون پیشنهاد';old.append(z);for(const i of candidates){const o=document.createElement('option');o.value=String(i.id);o.textContent=i.name;old.append(o)}old.value=String(selected)}}
async function saveProductStructure(itemId){const f=$('[data-item-form]'),family=familyForItem(itemId),variantEnabled=!!$('[data-variant-enabled]')?.checked;if(variantEnabled){const members=variantDraft.map((r,idx)=>({item_id:Number(r.item_id),label:String(r.label||'').trim(),sort_order:(idx+1)*10})).filter(r=>r.item_id>0);if(members.length<2||members.some(r=>!r.label))throw new Error('برای خانواده Variant حداقل دو آیتم با عنوان کامل لازم است.');if(!members.some(r=>Number(r.item_id)===Number(itemId)))throw new Error('خود این آیتم باید یکی از Variantهای خانواده باشد.');await post({action:'variant_family_save',id:Number(family?.id||0),name:$('[data-variant-name]').value,description:$('[data-variant-description]').value,category_id:Number(f.elements.category_id.value),sort_order:Number(f.elements.sort_order.value||0),featured:f.elements.featured.checked,members})}else if(family){await post({action:'variant_family_remove',id:Number(family.id)})}const suggestions=[0,1].map(idx=>Number($(`[data-suggestion="${idx}"]`)?.value||0)).filter(Boolean);if(new Set(suggestions).size!==suggestions.length)throw new Error('دو پیشنهاد باید متفاوت باشند.');await post({action:'suggestions_save',source_item_id:itemId,suggested_item_ids:suggestions});const bundle=bundleForItem(itemId),bundleEnabled=!!$('[data-bundle-enabled]')?.checked;if(bundleEnabled){const comps=bundleDraft.map((r,idx)=>({component_item_id:Number(r.component_item_id),mode:r.mode,quantity:Number(r.quantity||1),price_delta:Number(r.price_delta||0),sort_order:(idx+1)*10})).filter(r=>r.component_item_id>0);if(!comps.length)throw new Error('برای ترکیب حداقل یک جزء لازم است.');await post({action:'bundle_save',bundle_item_id:itemId,choice_label:$('[data-bundle-choice-label]').value,components:comps})}else if(bundle){await post({action:'bundle_remove',bundle_item_id:itemId})}}
async function retireItem(i){if(!confirm(`«${i.name}» از فروش روزمره خارج و به آرشیو منتقل شود؟ تاریخچه حذف نمی‌شود.`))return;const note=prompt('یادداشت آرشیو (اختیاری):','');if(note===null)return;try{await post({action:'item_retire',id:Number(i.id),note});selectedItems.delete(Number(i.id));await refresh('آیتم به آرشیو منتقل شد.')}catch(e){actionError(e,'آرشیو آیتم انجام نشد')}}
