function renderArchive(){const ib=$('[data-archive-items]'),cb=$('[data-archive-categories]');if(!ib||!cb)return;ib.replaceChildren();cb.replaceChildren();const q=$('[data-archive-search]')?.value||'';const items=(snap.archived_items||[]).filter(i=>includesText([i.name,i.item_code,i.category_name,i.retired_note].join(' '),q));const cats=(snap.archived_categories||[]).filter(c=>includesText([c.name,c.retired_note].join(' '),q));const rc=$('[data-archive-result-count]');if(rc)rc.textContent=`${L.integer(items.length+cats.length)} نتیجه`;if(!items.length)tableEmpty(ib,6,'آیتم آرشیوشده‌ای پیدا نشد.');for(const i of items){const tr=document.createElement('tr');itemIdentityCell(tr,i);cell(tr,'دسته',i.category_name||'—');cell(tr,'آخرین قیمت',L.money(i.price));cell(tr,'تاریخ آرشیو',i.retired_at||'—');cell(tr,'یادداشت',i.retired_note||'—');const ac=document.createElement('td');ac.dataset.label='عملیات';ac.append(button('بازگردانی به کاتالوگ',async()=>{try{await post({action:'item_restore',id:Number(i.id)});await refresh('آیتم به حالت غیرفعال و مخفی بازگردانده شد.')}catch(e){actionError(e,'بازگردانی انجام نشد')}}));tr.append(ac);ib.append(tr)}if(!cats.length)tableEmpty(cb,4,'دسته آرشیوشده‌ای پیدا نشد.');for(const c of cats){const tr=document.createElement('tr');cell(tr,'دسته',c.name);cell(tr,'تاریخ آرشیو',c.retired_at||'—');cell(tr,'یادداشت',c.retired_note||'—');const ac=document.createElement('td');ac.dataset.label='عملیات';ac.append(button('بازگردانی',async()=>{try{await post({action:'category_restore',id:Number(c.id)});await refresh('دسته به حالت غیرفعال بازگردانده شد.')}catch(e){actionError(e,'بازگردانی دسته انجام نشد')}}));tr.append(ac);cb.append(tr)}}
function inventoryUnitLabel(u){return u==='g'?'گرم':u==='ml'?'میلی‌لیتر':'عدد'}
function recipeInventoryItems(){return snap.inventory_recipe?.inventory_items||[]}
function recipeForMenuItem(id){return snap.inventory_recipe?.recipes?.[String(id)]||snap.inventory_recipe?.recipes?.[Number(id)]||null}
function recipeItemById(id){return recipeInventoryItems().find(x=>Number(x.id)===Number(id))}
