async function saveOrdering(kind,scope,ids){const list=$('[data-order-list]');list?.setAttribute('aria-busy','true');try{if(kind==='category')await post({action:'category_reorder',menu_id:Number(scope),ordered_ids:ids});else await post({action:'item_reorder',category_id:Number(scope),ordered_ids:ids});if(kind==='category'){ids.forEach((id,idx)=>{const row=categoryById(id);if(row){row.menu_sort_orders=row.menu_sort_orders||{};row.menu_sort_orders[String(scope)]=(idx+1)*10}})}else ids.forEach((id,idx)=>{const row=itemById(id);if(row)row.sort_order=(idx+1)*10});renderOrderDialog();renderCategories();renderItems();toast('ترتیب ذخیره شد.')}catch(e){actionError(e,'ذخیره ترتیب انجام نشد')}finally{list?.removeAttribute('aria-busy')}}
