function currentItemPage(){const all=filteredItems(),ctx=itemReorderContext();if(ctx)return{all,rows:all,page:1,pages:1,ctx};const pages=Math.max(1,Math.ceil(all.length/ITEM_PAGE_SIZE));itemPage=Math.min(Math.max(1,itemPage),pages);const start=(itemPage-1)*ITEM_PAGE_SIZE;return{all,rows:all.slice(start,start+ITEM_PAGE_SIZE),page:itemPage,pages,ctx}}
