function render(){renderSectionStatus();renderSummary();renderMenuStrip();refillCategoryFilters();renderMenus();renderCategories();renderItems();renderArchive();renderTags()}
async function refresh(done=''){root.setAttribute('aria-busy','true');status('');try{const j=await request(`${api}?action=snapshot`);snap=j.snapshot;catalogReady=true;selectedItems=new Set([...selectedItems].filter(id=>snap.items.some(i=>Number(i.id)===id)));render();setCreateReady(true);if(done)toast(done)}catch(e){catalogReady=false;setCreateReady(false);status(e.message,true)}finally{root.removeAttribute('aria-busy')}}
function editMenu(m=null){const f=$('[data-menu-form]');f.reset();const count=m?itemCountForMenu(m.id):0;$('[data-menu-dialog-title]').textContent=m?`ویرایش منوی ${m.name}`:'منوی جدید';$('[data-menu-dialog-context]').textContent=m?`${L.integer(count)} آیتم در این منو · ${scheduleText(m)}`:'نام، وضعیت و زمان سرو این منو را مشخص کن.';f.elements.id.value=m?.id||'';f.elements.name.value=m?.name||'';f.elements.status.value=m?.status||'draft';f.elements.sort_order.value=m?.sort_order||0;f.elements.daily_start.value=m?.daily_start?String(m.daily_start).slice(0,5):'';f.elements.daily_end.value=m?.daily_end?String(m.daily_end).slice(0,5):'';dayChecks('menu-days','schedule_days',m?.schedule_days||[]);openDialog('menu')}
function refillCategorySelect(selector,selected=0){const s=$(selector);s.replaceChildren();for(const c of snap.categories.filter(c=>c.lifecycle_status!=='retired')){const o=document.createElement('option');o.value=String(c.id);o.textContent=`${c.name}${c.lifecycle_status==='inactive'?' · غیرفعال':''}`;s.append(o)}if([...s.options].some(o=>Number(o.value)===Number(selected)))s.value=String(selected)}
