function editItem(i=null){const f=$('[data-item-form]');f.reset();f.querySelectorAll('.sc-entity-editor__advanced').forEach(d=>d.open=false);itemValidation('');f.elements.id.value=i?.id||'';f.elements.name.value=i?.name||'';f.elements.description.value=i?.description||'';f.elements.price.value=i?.price??'';refillCategorySelect('[data-item-category]',i?.category_id||snap.categories[0]?.id||0);f.elements.sellable_kind.value=i?.sellable_kind||'menu_item';f.elements.preparation_station.value=i?.preparation_station||'cold_bar';f.elements.sort_order.value=i?.sort_order||0;f.elements.lifecycle_status.value=i?.lifecycle_status||'active';for(const k of ['available','guest_visible','staff_visible','featured','takeaway_allowed'])if(f.elements[k])f.elements[k].checked=i?!!i[k]:['available','guest_visible','staff_visible','takeaway_allowed'].includes(k);f.elements.daily_start.value=i?.daily_start?String(i.daily_start).slice(0,5):'';f.elements.daily_end.value=i?.daily_end?String(i.daily_end).slice(0,5):'';f.elements.schedule_start.value=dtLocal(i?.schedule_start);f.elements.schedule_end.value=dtLocal(i?.schedule_end);dayChecks('item-days','schedule_days',i?.schedule_days||[]);refillItemMenus(i?i.menu_ids:null);tagChecks(i?.tag_ids||[]);f.dataset.imagePath=i?.image_path||'';renderCurrentMedia('[data-item-media-current]',f.dataset.imagePath);resetRecipeDraft(i);setupProductStructureEditor(i);openDialog('item');I?.markClean?.(f)}
