function fullPayload(i,override={}){return{action:'item_save',id:Number(i.id),name:i.name,description:i.description||'',price:i.price,category_id:Number(i.category_id),sellable_kind:i.sellable_kind,preparation_station:i.preparation_station,sort_order:Number(i.sort_order||0),lifecycle_status:i.lifecycle_status||'active',available:!!i.available,guest_visible:!!i.guest_visible,staff_visible:!!i.staff_visible,featured:!!i.featured,takeaway_allowed:!!i.takeaway_allowed,menu_ids:i.menu_ids||[],tag_ids:i.tag_ids||[],schedule_days:i.schedule_days||[],daily_start:i.daily_start?String(i.daily_start).slice(0,5):'',daily_end:i.daily_end?String(i.daily_end).slice(0,5):'',schedule_start:dtLocal(i.schedule_start),schedule_end:dtLocal(i.schedule_end),...override}}
function openMediaPicker(type,row){mediaTarget={type,id:Number(row.id)};mediaSelected=mediaKey(row.image_path);$('[data-media-context]').textContent=`${type==='item'?'آیتم':'دسته'}: ${row.name}`;$('[data-media-search]').value='';renderMediaPicker();openDialog('media')}
function renderMediaPicker(){const grid=$('[data-media-grid]'),q=$('[data-media-search]')?.value||'';grid.replaceChildren();const rows=(snap.media||[]).filter(m=>includesText([m.original_name,m.alt_text].join(' '),q));if(!rows.length){grid.append(el('div','sc-empty','تصویر فعالی در آلبوم پیدا نشد.'));return}for(const m of rows){const b=el('button','sc-media-picker-card');b.type='button';b.dataset.mediaKey=m.media_key;b.setAttribute('role','option');b.setAttribute('aria-selected',m.media_key===mediaSelected?'true':'false');if(m.media_key===mediaSelected)b.classList.add('is-selected');const img=document.createElement('img');img.src=imageUrl(m.media_key);img.alt=m.alt_text||m.original_name||'';b.append(img,el('span','',m.original_name||'تصویر'));b.addEventListener('click',()=>{mediaSelected=m.media_key;renderMediaPicker()});grid.append(b)}}
async function applyMedia(){if(!mediaTarget)return;try{const payload=mediaTarget.type==='item'?{action:'media_assign_item',item_id:mediaTarget.id,media_key:mediaSelected}:{action:'media_assign_category',category_id:mediaTarget.id,media_key:mediaSelected};await post(payload);closeDialog($('[data-dialog="media"]'));await refresh('تصویر ذخیره شد.')}catch(e){actionError(e,'ذخیره تصویر انجام نشد')}}
function bindFilters(){for(const s of ['[data-item-search]','[data-item-category-filter]','[data-item-status]','[data-item-audience]'])$(s)?.addEventListener(s.includes('search')?'input':'change',()=>{itemPage=1;renderItems()});for(const s of ['[data-category-search]','[data-category-audience]','[data-category-status]','[data-category-order-menu]'])$(s)?.addEventListener(s.includes('search')?'input':'change',renderCategories);for(const s of ['[data-menu-search]','[data-menu-status]'])$(s)?.addEventListener(s.includes('search')?'input':'change',renderMenus)}
$$('[data-open]').forEach(b=>b.addEventListener('click',()=>({menu:editMenu,category:editCategory,item:editItem,tag:editTag}[b.dataset.open]?.())));
$$('[data-open-ordering]').forEach(b=>b.addEventListener('click',()=>openOrdering(b.dataset.openOrdering)));$('[data-order-scope]')?.addEventListener('change',renderOrderDialog);
