$('[data-recipe-item]')?.addEventListener('change',()=>{const inv=recipeItemById(Number($('[data-recipe-item]')?.value||0)),unit=$('[data-recipe-unit]'),add=$('[data-recipe-add]');if(unit)unit.textContent=inv?inventoryUnitLabel(inv.base_unit):'—';if(add)add.disabled=!inv});$('[data-recipe-add]').addEventListener('click',()=>{const value=$('[data-recipe-item]'),quantity=$('[data-recipe-quantity]');const id=Number(value?.value||0),raw=typeof L.normalizeNumber==='function'?L.normalizeNumber(quantity?.value||'',{decimal:false,signed:false}):String(quantity?.value||'').trim();const inv=recipeItemById(id);if(!inv){toast('یک ماده انبار را از نتایج جست‌وجو انتخاب کن.','warning','دستور مصرف');return}if(!/^\d+$/.test(raw)||Number(raw)<=0){toast(`مقدار مصرف ${inv.name} باید یک عدد صحیح بیشتر از صفر با واحد ${inventoryUnitLabel(inv.base_unit)} باشد.`,'warning','دستور مصرف');return}recipeDraft.push({inventory_item_id:id,quantity_base:raw,quantity_status:'known',source_note:'افزوده‌شده دستی'});I?.markDirty?.($('[data-item-form]'));if(quantity)quantity.value='';renderRecipeEditor()});
