$('[data-item-form]').addEventListener('submit',async e=>{e.preventDefault();if(e.submitter?.value!=='submit'){itemValidation('');closeDialog(e.currentTarget);return}const f=e.currentTarget;itemValidation('');await SoknaUI.busy(f,async()=>{let itemSaved=false;try{const saved=await post({action:'item_save',id:Number(f.elements.id.value||0),name:f.elements.name.value,description:f.elements.description.value,price:f.elements.price.value,category_id:Number(f.elements.category_id.value||0),sellable_kind:f.elements.sellable_kind.value,preparation_station:f.elements.preparation_station.value,sort_order:Number(f.elements.sort_order.value||0),lifecycle_status:f.elements.lifecycle_status.value,available:f.elements.available.checked,guest_visible:f.elements.guest_visible.checked,staff_visible:f.elements.staff_visible.checked,featured:f.elements.featured.checked,takeaway_allowed:f.elements.takeaway_allowed.checked,menu_ids:checkedValues(f,'menu_ids'),tag_ids:checkedValues(f,'tag_ids'),schedule_days:checkedValues(f,'schedule_days'),daily_start:f.elements.daily_start.value,daily_end:f.elements.daily_end.value,schedule_start:f.elements.schedule_start.value,schedule_end:f.elements.schedule_end.value});itemSaved=true;const itemId=Number(saved?.result?.id||f.elements.id.value||0);const recipeUnavailable=!!sectionError('inventory_recipe');if(!recipeUnavailable)await post({action:'recipe_save',menu_item_id:itemId,reviewed:!!recipeReviewState.reviewed,complete:!!recipeReviewState.complete,components:recipeDraft.map(c=>({inventory_item_id:Number(c.inventory_item_id),quantity_base:typeof L.normalizeNumber==='function'?L.normalizeNumber(c.quantity_base||'',{decimal:false,signed:false}):String(c.quantity_base||''),quantity_status:String(c.quantity_status||'known'),source_note:c.source_note||null}))});await saveProductStructure(itemId);I?.markClean?.(f);closeDialog(f);await refresh(recipeUnavailable?'آیتم ذخیره شد؛ دستور مصرف به‌دلیل در دسترس نبودن انبار بدون تغییر ماند.':'آیتم و ساختار محصول ذخیره شد.')}catch(err){itemValidation(err?.message||'ذخیره انجام نشد.');actionError(err,itemSaved?'آیتم ذخیره شد؛ یکی از تنظیمات تکمیلی ذخیره نشد':'ذخیره آیتم انجام نشد')}})});
$('[data-item-quick-form]').addEventListener('submit',async e=>{e.preventDefault();if(e.submitter?.value!=='submit'){closeDialog(e.currentTarget);return}const f=e.currentTarget,i=itemById(Number(f.elements.id.value));if(!i)return;await SoknaUI.busy(f,async()=>{try{const categoryId=Number(f.elements.category_id.value),allowed=categoryById(categoryId)?.menu_ids||[],menus=(i.menu_ids||[]).filter(id=>allowed.includes(Number(id)));await post(fullPayload(i,{name:f.elements.name.value,price:f.elements.price.value,category_id:categoryId,menu_ids:menus,lifecycle_status:f.elements.lifecycle_status.value,guest_visible:f.elements.guest_visible.checked,staff_visible:f.elements.staff_visible.checked,available:f.elements.available.checked,featured:f.elements.featured.checked}));closeDialog(f);await refresh('ویرایش سریع ذخیره شد.')}catch(err){actionError(err)}})});
